from time import sleep
from typing import List, Optional, Pattern, Tuple, Dict, Union

from ta_tti_collector import get_tts_bin, get_tts_path
from ta_tti_collector.cell_mapping import CellMapping
from ta_tti_collector.collectors.collector_abstract_interface import TtiCollectorInterface
from ta_tti_collector.utils import cell_is_nbiot, change_file_permissions, copy_file, delete_files, \
    file_exists, get_filenames_containing_string, get_simple_logger, kill_all_processes_containing_name, \
    get_fsm_sw_version, run_process
from ta_tti_collector.wft import WftClient
from ta_tti_collector.telemetry import get_telemetry_instance

SERVER_PATH_TEMPLATE = '/tmp/TtiTraceServer{}/'
CLIENT_PATH_NAME = 'TTITraceStreamingClient'
FILES_DIR = '/tmp/tti_parser/'
ENB_IP = {'vm1': '192.168.255.129', 'vm2': '10.0.1.4', 'vm3': '10.0.1.6', 'vm4': '10.0.1.8'}
FILE_PERM = 0o755
TRACE_SIZE_IN_MB = 100
CLIENT_PORT = 15007
ENB_PORT = 15002
F_NAME_PATTERN = 'tti_trace_enb_{eid}_LNCEL_{cid}_{d}_alias_{al}_{ts}.dat'
F_NAME_REGEX = compile('([DU]L)?_?(PDCCH)?_?(\\d{1,2}[a-zA-Z]{3}[\\d+_]+)?\\.dat')
SERVER_CFG_TEMPLATE = '''<settings>
    <dat_file_size_mb_limit>{fz}</dat_file_size_mb_limit>
    <endian>BIG</endian>
    <client_port>{cp}</client_port>
    <enb>
        <index>0</index>
        <enb_address>{eip}</enb_address>
        <enb_port>{ep}</enb_port>
        <syscom_address>{mid}</syscom_address>
        <cell_mapping>{cm}
        </cell_mapping>
    </enb>
</settings>'''
CLIENT_CFG_TEMPLATE = '''<settings>
    <host_name>127.0.0.1</host_name>
    <port>{clp}</port>
    <endian>BIG</endian>
</settings>'''
CELL_MAPPING_TEMPLATE = '''
    <cell>
        <cell_id>{lncel}</cell_id>
            <mac_ul_address>{MACULTTI}</mac_ul_address>
            <mac_dl_address>{MACDLTTI}</mac_dl_address>
    </cell>'''

MAX_BUILD_PARENT_COUNT = 5
SIMILAR_BUILD_MAX_DAYS_BACK = 5

tl = get_telemetry_instance()

class TtiTraceStreamingCollector(TtiCollectorInterface):
    """Collect TTI trace from eNB."""

    def __init__(self, dest_dir='/tmp/tti_trace_results', logger=None):
        # type: (str, Optional[Logger]) -> None
        """
        Setup collecting TTI trace.

        :param dest_dir: destination directory for logs
        :param logger: Logger instance
        """
        self.logger = get_simple_logger(logger=logger, logger_name='tti_collector', stream=True,
                                        full_path=path.join(dest_dir, 'ta_tti_collector.log'))
        self.trace_dir = self._check_logs_dir(dest_dir)
        self.sw_version = self.get_sw_version()
        self.wft_client = WftClient(self.logger)
        self.selected_build = None
        self.files_dir = path.join(FILES_DIR, self.sw_version)
        self.fdd_parser_dir = path.join(self.files_dir, 'FDD_parser')
        self.tdd_parser_dir = path.join(self.files_dir, 'TDD_parser')
        self.server_files = ['logs.conf', 'TTITraceServer.linux']
        self.client_files = ['TTITraceStreamingClient.linux']
        self.fdd_parser_files = ['tti_trace_parser_wmp-linux.exe',
                                 'dl_high_config.txt',
                                 'ul_high_config.txt',
                                 'pdcch_high_config.txt']
        self.tdd_parser_files = ['DevC_tti_trace_parser_64', 'dl_high_config.txt', 'ul_high_config.txt']
        self.tools_packages = {'FDD': 'TtiTracer.zip', 'TDD': 'pstools.zip'}
        self._register = {}
        self.running_servers = {}
        self.running_clients = {}
        self.cell_mapping = {}
        self.ready_enbs = []

    @staticmethod
    def server_path(enb):
        # type: (str) -> str
        """Path to server files."""
        return SERVER_PATH_TEMPLATE.format(enb)

    def client_path(self, enb):
        # type: (str) -> str
        """Path to client files."""
        return path.join(self.server_path(enb), CLIENT_PATH_NAME)

    def get_sw_version(self):
        """Get sw_version"""
        version = get_fsm_sw_version(self.logger, 'enb')
        return _correct_build_for_trunk(version)

    def register(self, value):
        # type: (dict)  -> None
        """Add value to registry property as dict."""
        with tl.trace("register"):
            try:
                cur_enb = self._fetch_enb_id(value)
            except (KeyError, IndexError):
                cur_enb = u'1'

            with tl.trace("tti_register") as trace:
                cur_cell_ids = value[list(value.keys())[0]]['cells'].keys()
                self.logger.debug('Trying to add following cells: {}'.format(cur_cell_ids))
                event_data = {"cells:": "".join(cur_cell_ids)}
                trace.set_attributes(event_data)

                self._register.update(value)
                self._register[list(value).pop()]['DL'] = []
                self._register[list(value).pop()]['UL'] = []
                self._register[list(value).pop()]['PDCCH'] = []

                self.logger.debug('Added entry: {}'.format(value))
                if cur_enb not in self.ready_enbs:
                    self._prepare_tti_trace(enb=cur_enb)

    def start_collecting(self, alias):
        # type: (str) -> None
        """
        Start TTI server and TTI client for cells requested in alias.
        Server is started once per eNb in background. Any attempt to communicate with it, will end connection.
        :param alias: alias
        """
        cells = self._register[alias]['cells']
        enb = self._register[alias]['enb']
        self.logger.info('Alias: {} start collecting for: cells {} @eNb {}'.format(alias, cells, enb))

        if not self.running_servers.get(enb, None):
            self.start_server(enb)

        available_cells = [c_inf['lnCel'] for c_inf in self.cell_mapping[enb].cell_mapping]
        self.logger.debug('Available cells from cell mapping {}'.format(available_cells))
        for cell in cells:
            if int(cell) in available_cells:
                if int(cell) in self.running_clients[enb]:
                    err_info = 'Tracing for LNCEL-{id} already started with some alias at enb-{e}. ' \
                               'Stop tracing for all other aliases referencing LNCEL-{id}.'.format(id=cell, e=enb)
                    self.logger.debug(err_info)
                    tl.update("start_collecting", 1, {"type": "enb", "status": "fail"})
                    raise Exception(err_info)
                self._execute_tts_client_cmd('start', cell, alias, enb)
                self.running_clients[enb].append(int(cell))
            else:
                self.logger.warning('TTI trace cannot be gathered for enb-{} LNCEL-{} '
                                    'cell NOT discovered in cell mapping.'.format(enb, cell))

        tl.update("start_collecting", 1, {"status": "success", "type": "enb"})

    def start_server(self, enb):
        # type: (str) -> None
        """Run server daemon in background."""
        _server = get_tts_bin('server', enb)
        self.running_servers[enb] = run_process(self.logger, _server, get_tts_path('server', enb), enb)
        self.running_clients[enb] = []
        self.logger.debug('TT SERVER {} started'.format(_server))

    def stop_collecting(self, alias):
        # type: (str) -> None
        """
        Stop collecting tti traces for cells included in alias.
        :param alias: alias name
        """
        cells = self._register[alias]['cells']
        enb = self._register[alias]['enb']
        self.logger.info('Alias: {} stop collecting for: cells {} @eNb {}'.format(alias, cells, enb))

        for cell in cells:
            if int(cell) not in self.running_clients[enb]:
                self.logger.debug('Running client for LNCEL-{} was not found. Stop ommited.'.format(cell))
                tl.update("stop_collecting", 1, {"status": "fail", "type": "enb"})
                return

            self._execute_tts_client_cmd('stop', cell, alias, enb)
            for fp in get_filenames_containing_string(
                    self.logger, get_tts_path('server', enb), '*{}_{}*.dat'.format(alias, cell)):
                direction, new_fp = self._rename_and_move_file(alias, cell, enb, fp)
                self._register[alias][direction].append(new_fp)
            self.running_clients[enb].remove(int(cell))

        tl.update("stop_collecting", 1, {"status": "success", "type": "enb"})

    def post_test_cleanup(self):
        # type: () -> None
        """Cleanup any hanging TTS process mess."""
        self._kill_servers()
        self._clear_internals()

    def renew_cellmapping(self):
        # type: () -> None
        """
        Renew cell mapping for all enbs.
        :return:
        """
        for enb in self.ready_enbs:
            new_cm = CellMapping(ENB_IP['vm{}'.format(enb)], self.logger)()
            if new_cm != self.cell_mapping[enb]:
                self.cell_mapping[enb] = new_cm
                self.write_server_xml(enb)
                self._kill_servers()
                self.start_server(enb)

    def cell_is_onair(self, cell_dict, enb):
        # type: (dict, str) -> bool
        """Return True if both cores are not zeros."""
        is_onair = all([cell_dict['MACULTTI'], cell_dict['MACDLTTI']])
        if is_onair:
            self.logger.debug("TTI trace can be gathered for enb-{} LNCEL-{}".
                              format(enb, cell_dict['lnCel']))
        return is_onair

    def generate_cell_mapping_structure(self, enb):
        # type (str) -> str
        """
        Fill part of xml setting with cell mapping.
        :param enb: enb id
        :return: formatted str
        """
        cell_mapping = ''
        for cell_dict in self.cell_mapping[enb].cell_mapping:
            if self.cell_is_onair(cell_dict, enb):
                cell_mapping += self._fill_cell_info(cell_dict)
            else:
                nbiot = cell_is_nbiot(cell_dict)
                if nbiot:
                    self.logger.debug('enb-{} LNCEL-{} is NBIoT cell. Copying DL core id to UL.'.
                                      format(enb, cell_dict['lnCel']))
                    cell_mapping += self._fill_cell_info(cell_dict, is_nbiot=True)
                else:
                    cell_mapping += self._fill_cell_info(cell_dict)

        self.logger.debug('Filling cell mapping - done.')
        return cell_mapping

    def write_server_xml(self, enb):
        # type: (str) -> None
        """
        Write cell mapping to xml with settings.

        :param enb: enb id
        :return:
        """
        c_port = CLIENT_PORT + int(enb)
        e_port = ENB_PORT + int(enb)
        xml = path.join(get_tts_path('server', enb), 'settings.xml')
        master_nid = self._get_used_master_nid(xml)
        cell_mapping = self.generate_cell_mapping_structure(enb)
        with open(xml, 'w') as settings:
            content = SERVER_CFG_TEMPLATE.format(fz=TRACE_SIZE_IN_MB, cp=c_port, eip=ENB_IP['vm{}'.format(enb)],
                                                 ep=e_port, mid=master_nid, cm=cell_mapping)
            settings.write(content)
            self.logger.debug('Generated XML server settings for eNB {}:\n{}'.format(enb, content))

    def copy_included_tts_files_as_recovery_action(self, enb):
        # type: (str) -> None
        """In case of missing files for TTS in TtiTracer.zip archive - copy included files."""
        base_path = path.abspath(path.join(path.dirname(path.dirname(__file__)), 'tts_files'))
        copy_file(self.logger, path.join(base_path, self.server_files[0]), self.server_path(enb))
        change_file_permissions(self.logger, path.join(self.server_path(enb), self.server_files[0]), FILE_PERM)
        copy_file(self.logger, path.join(base_path, self.server_files[1]), self.server_path(enb))
        change_file_permissions(self.logger, path.join(self.server_path(enb), self.server_files[1]), FILE_PERM)

        copy_file(self.logger, path.join(base_path, self.client_files[0]), self.client_path(enb))
        change_file_permissions(self.logger, path.join(self.client_path(enb), self.client_files[0]), FILE_PERM)

    def copy_included_parser_files_as_recovery_action(self):
        # type: (str) -> None
        """In case of missing parser files - copy included files."""
        base_path = path.abspath(path.join(path.dirname(path.dirname(__file__)), 'parser_files'))
        for parser_file in self.fdd_parser_files:
            copy_file(self.logger, path.join(base_path, "FDD", parser_file), self.fdd_parser_dir)
            change_file_permissions(self.logger, path.join(self.fdd_parser_dir, parser_file), FILE_PERM)
        for parser_file in self.tdd_parser_files:
            copy_file(self.logger, path.join(base_path, "TDD", parser_file), self.tdd_parser_dir)
            change_file_permissions(self.logger, path.join(self.tdd_parser_dir, parser_file), FILE_PERM)

    @staticmethod
    def _fill_cell_info(cell_dict, is_nbiot=False):
        # type: (dict, bool) -> str
        """Switch UL core to DL if cell is NBIoT"""
        uplink = cell_dict['MACDLTTI_raw'] if is_nbiot else cell_dict['MACULTTI_raw']
        return CELL_MAPPING_TEMPLATE.format(lncel=cell_dict['lnCel'],
                                            MACULTTI=uplink,
                                            MACDLTTI=cell_dict['MACDLTTI_raw'])

    @staticmethod
    def _fetch_enb_id(value):
        # type: (dict) -> str
        return value[list(value.keys())[0]]['enb']

    @staticmethod
    def extract_from_filename(f, regex):
        # type: (str, Pattern) -> Tuple[str, str, str]
        """
        Extract part of string as output.
        :param f: filename
        :param regex: regex compiled object
        :return: Tuple of strings
        """
        re_object = regex.search(f)
        direction = re_object.group(1)
        pdcch = re_object.group(2)
        timestamp = re_object.group(3)
        return direction, pdcch, timestamp

    def _rename_and_move_file(self, alias, cell, enb, fp):
        direction, pdcch, stamp = self.extract_from_filename(fp, F_NAME_REGEX)
        if not stamp:
            stamp = datetime.now().strftime("%d%b%Y%_H_%M_%S")
        if pdcch:
            direction = pdcch
        new_fp = path.join(
            self.trace_dir, F_NAME_PATTERN.format(eid=enb, cid=cell, d=direction, al=alias, ts=stamp))
        move(fp, new_fp)
        self.logger.debug('File {} renamed and copied to {}'.format(fp, new_fp))
        return direction, new_fp

    def _prepare_tti_trace(self, enb):
        # type: (str) -> None
        """
        Prepare TTI Server and Client binary files and create all needed configuration files.

        :param enb: eNb number 1 to 4 related to VM as well
        """
        self._create_base_dir()
        self._create_tts_dir(enb)
        self._create_parsers_dir()

        try:
            ttitracer_archive = self.download_package(self.tools_packages['FDD'])
            pstools_archive = self.download_package(self.tools_packages['TDD'])
            self._extract_tts_files_from_archive(ttitracer_archive, enb)
            self._extract_parser_files_from_archive(ttitracer_archive, self.fdd_parser_files, self.fdd_parser_dir)
            self._extract_parser_files_from_archive(pstools_archive, self.tdd_parser_files, self.tdd_parser_dir)
        except Exception as e:
            self.logger.warning("Download package failed due to: {}. Copy included files as recovery action".format(e))
            self.copy_included_tts_files_as_recovery_action(enb)
            self.copy_included_parser_files_as_recovery_action()
        self.logger.debug('TTS files ready at {}'.format(self.server_path(enb)))
        self.cell_mapping[enb] = CellMapping(ENB_IP['vm{}'.format(enb)], self.logger)()
        self._generate_server_cfg(enb)
        self._generate_client_cfg(enb)
        self.ready_enbs.append(enb)
        self.logger.debug('Prepare phase for enb-{} ended. Ready eNBs: {}'.format(enb, self.ready_enbs))

    def _extract_tts_files_from_archive(self, ttitracer_archive, enb):
        # type: (str, str) -> None
        unpacked_server_files = \
            get_extracted_selected_zip_files(self.logger, self.server_path(enb), ttitracer_archive, self.server_files)
        self._copy_unpacked_tti_files(unpacked_server_files, self.server_path(enb))

        unpacked_client_files = \
            get_extracted_selected_zip_files(self.logger, self.client_path(enb), ttitracer_archive, self.client_files)
        self._copy_unpacked_tti_files(unpacked_client_files, self.client_path(enb))

    def _extract_parser_files_from_archive(self, ttitracer_archive, files, dst):
        unpacked_files = \
            get_extracted_selected_zip_files(self.logger, self.files_dir, ttitracer_archive, files)
        self._copy_unpacked_tti_files(unpacked_files, dst)

    def _create_base_dir(self):
        # type: () -> None
        try:
            makedirs(self.files_dir)
        except OSError:
            pass

    def _create_tts_dir(self, enb):
        # type: (str) -> None
        try:
            makedirs(self.client_path(enb))
        except OSError:
            pass

    def _create_parsers_dir(self):
        # type: () -> None
        try:
            mkdir(self.fdd_parser_dir)
            mkdir(self.tdd_parser_dir)
        except OSError:
            pass

    def _copy_unpacked_tti_files(self, files, dst):
        # type: (Dict[str, str], str) -> None
        for fn, file_path in files.items():
            copy_file(self.logger, file_path, dst)
            change_file_permissions(self.logger, path.join(dst, fn), FILE_PERM)

    def _generate_server_cfg(self, enb, timeout=5):
        # type: (str) -> None
        server = get_tts_bin('server', enb)
        enb_port = ENB_PORT + int(enb)
        server_cfg = ' --config --enb {enb_ip} {port}'.format(enb_ip=ENB_IP['vm{}'.format(enb)], port=enb_port)

        if self.running_servers.get(enb) is None:
            kill_all_processes_containing_name(self.logger, server)

        self.logger.debug('Try to autogenerate TT SERVER cfg.')
        run_process(self.logger, server, get_tts_path('server', enb), enb, params=server_cfg, communicate=True)

        self.logger.debug('TT SERVER cfg for enb {} auto generation - done.'.format(enb))
        self.write_server_xml(enb)

    def _get_used_master_nid(self, xml):
        # type: (str) -> str
        try:
            with open(xml, 'r') as f:
                master_nid = search('<syscom_address>(\\w+)</syscom_address>', f.read()).group(1)
                self.logger.debug('TT SERVER cfg. master_nid used in settings.xml: {}'.format(master_nid))
                return master_nid
        except (IOError, OSError, AttributeError) as e:
            self.logger.debug('TT SERVER cfg issue: {}'.format(e))

    def _generate_client_cfg(self, enb):
        # type: (str) -> None
        client_port = 15007 + int(enb)
        client_settings = path.join(get_tts_path('client', enb), 'client_settings.xml')
        with open(client_settings, 'w') as settings:
            content = CLIENT_CFG_TEMPLATE.format(clp=client_port)
            settings.write(content)
            self.logger.debug('Generated XML client settings for eNB {}:\n{}'.format(enb, content))

    def _execute_tts_client_cmd(self, action, cell_id, name, enb):
        # type: (str, int, str, str) -> None
        timeout = 2.0
        delay = 0.5
        tts_client_template = ' --params --command {a} --cellID {c} --name {n}'.format(a=action, c=cell_id, n=name)
        client = get_tts_bin('client', enb)
        cmd = split(client + tts_client_template)

        client_process = run_process(self.logger, client, get_tts_path('client', enb), enb, params=tts_client_template)

        while client_process.poll() is None and timeout > 0:
            self.logger.debug('Awaiting result from client cmd {}. Timeout left: {}s'.format(cmd, timeout))
            sleep(delay)
            timeout -= delay

        if client_process.returncode == 0:
            self.logger.debug('Successfully executed client cmd: {}'.format(cmd))
        elif client_process.returncode is None:
            self.logger.warning('Client command: {} failed for LNCEL-{}. Forcing kill.'.format(cmd, cell_id))
            client_process.kill()
            self.logger.debug('Murder committed.')

    def _cleanup_unwanted_traces(self, cells):
        # type: (dict) -> None
        """
        Searches through logs directory for tti traces that are not necessary for user and removes them.
        :param cells: dictionary with cells and directions
        """
        fn = '*_{cell}_{dir}*.dat*'
        info = 'Cell {c} - selected directions {d}.'
        server_path = get_tts_path(name='server', enb='1')
        for cell, params in cells.items():
            direction = params.get('direction', 'DLUL')
            self.logger.debug(info.format(c=cell, d=direction))
            regex = fn.format(cell=cell, dir=direction)
            if 'DLUL' not in direction.upper() or 'ULDL' not in direction.upper():
                self.logger.debug('Other direction will be deleted.')
                files = get_filenames_containing_string(self.logger, server_path, regex)
                delete_files(self.logger, files)

    def _kill_servers(self):
        for enb, server in self.running_servers.items():
            try:
                server.kill()
            except (CalledProcessError, AttributeError):
                kill_all_processes_containing_name(self.logger, get_tts_bin('server', enb))

    def _clear_collected_traces_from_register(self):
        """Clear trace filenames, but leave other info."""
        for k, v in self._register.items():
            for direction in ['UL', 'DL', 'PDCCH']:
                self._register[k][direction] = []

    def _clear_internals(self):
        self.logger.debug('Clearing internal state of Collector class.')
        self._clear_collected_traces_from_register()
        self.running_clients.clear()
        self.running_servers.clear()

    def download_package(self, name):
        # type: (str) -> str
        """Download package"""
        with tl.trace("download_package"):
            package_path = path.join(self.files_dir, name)
            if not file_exists(package_path):
                package_path = self._download_package(name, package_path)
            self.logger.debug('Package {} available at {}'.format(name, package_path))
            return package_path

    def _download_package(self, name, destination):
        with tl.trace("_download_package_from_remote"):
            downloaded_package = ''
            self.logger.debug(
                'Package {} with parser does not exist at {}. Trying to download it.'.format(name, destination))
            self._select_build()
            build = self.selected_build
            parent_count = 0
            while build and parent_count <= MAX_BUILD_PARENT_COUNT:
                url = self.wft_client.get_package_url(build, name)
                if url:
                    try:
                        with tl.trace("download_file") as trace:
                            event_data = {"build": build}
                            trace.set_attributes(event_data)
                            download_file(self.logger, url, destination)

                        self.logger.debug('Package {} downloaded from {} for build {}'.format(name, url, build))
                        downloaded_package = destination
                        self.selected_build = build
                        self.logger.debug('Selected build {} - parent build.'.format(self.selected_build))
                        break
                    except ValueError:
                        pass
                build = self.wft_client.get_parent_build(build)
                parent_count += 1

            if not downloaded_package:
                info = ('Cannot download package with name {}. '
                        'Possible similar builds exceeded. Check logs for more info.').format(name)
                tl.update("download_package", 1, {"status": "fail", "build": self.selected_build})
                self.logger.warning(info)
                raise Exception(info)

            tl.update("download_package", 1, {"status": "success", "build": self.selected_build})
            return destination

    def _select_build(self):
        if self.selected_build:
            self.logger.debug('Selected build already set to {}'.format(self.selected_build))
            return
        if self.wft_client.check_build_exists(self.sw_version):
            self.selected_build = self.sw_version
            self.logger.debug('Selected build {} - regular sw_version, build exists.'.format(self.selected_build))
            return
        self.selected_build = self._find_similar_build()
        if not self.selected_build:
            self.logger.debug('Cannot select a build - no similar build found.')
            return
        self.logger.debug('Selected build {} - similar build.'.format(self.selected_build))

    def _find_similar_build(self):
        build_pattern = self._correct_knife_pattern(self.sw_version)
        days_back = 1
        while days_back <= SIMILAR_BUILD_MAX_DAYS_BACK:
            self.logger.debug('Trying to find similar build for {}'.format(build_pattern))
            if build := self.wft_client.get_similar_build(build_pattern):
                return build
            build_pattern = self._correct_build_date(build_pattern)
            days_back += 1
        self.logger.warning('Cannot find similar build for {}'.format(self.sw_version))

    def _correct_build_date(self, build_pattern):
        parts = build_pattern.split('_')
        date = datetime.strptime(parts[3], '%y%m%d')
        new_date = date - timedelta(days=1)
        parts[3] = new_date.strftime('%y%m%d')
        return '_'.join(parts)

    def _correct_knife_pattern(self, build):
        # example knife SBTS00_ENB_9900_240618_1207465
        parts = build.split('_')
        parts[2] = '9999' if parts[0] == 'SBTS00' else '0000'
        return '_'.join(parts[:-1])


def download_file(logger, url, destination):
    # type: (Logger, str, str) -> None
    """
    Download file from URL.
    :param logger: logger instance
    :param url: url
    :param destination: path where file should be saved
    """
    retries = 2
    for attempt in range(retries):
        proxies = None if attempt % 2 == 0 else {"http": "", "https": ""}
        try:
            request = get(url, timeout=15.0, proxies=proxies, stream=True)
        except RequestException:
            logger.warning('Cannot get contents from url {}'.format(url))
            continue
        if request.status_code == 200:
            save_request_content_to_file(logger, request, destination)
            break
    else:
        msg = "File cannot be downloaded from {}".format(url)
        logger.warning(msg)
        raise ValueError(msg)


def save_request_content_to_file(logger, request, destination):
    # type: (Logger, Response, str) -> None
    """
    Write contents of request to file.
    :param logger: logger
    :param request: request
    :param destination: to put file
    """
    try:
        with open(destination, 'wb') as f:
            for chunk in request.iter_content(8192):
                f.write(chunk)
        logger.debug("File successfully downloaded to {}".format(destination))
    except (IOError, OSError) as e:
        logger.debug('Cannot save file at location {} due to: {}'.format(destination, e))
        raise


def get_extracted_selected_zip_files(logger, dst_dir, archive_path, filenames):
    # type: (Logger, str, str, List) -> Dict[str, str]
    """

    :param logger: Logger object
    :param dst_dir: path to drop extracted files
    :param archive_path: path to archive
    :param filenames: list of files to extract
    """
    extracted = {}
    found_items = {}
    with zipfile.ZipFile(archive_path, 'r') as ar:
        for fn in filenames:
            found_items[fn] = get_zipinfo_items(logger, ar.infolist(), fn)
        missing = [fn for fn, val in found_items.items() if not val]
        if missing:
            raise Exception('Required files were not found in zip {}. Extract cancelled.\n'
                            'Missing: {}'.format(archive_path, ' '.join(missing)))
        for fn, item in found_items.items():
            extracted[fn] = ar.extract(item, dst_dir)
    logger.debug('All required files found in archive {} '.format(archive_path))
    return extracted


def get_zipinfo_items(logger, zip_info, filename):
    # type: (Logger, List[zipfile.ZipInfo], List) -> Union[None, zipfile.ZipInfo]
    """
    Search through zip root tree and append item if filename at the end of tree matches.

    :param logger: Logger object
    :param zip_info: ZipInfo object
    :param filename: to be searched for in zip archive
    :return: List with ZipInfo objects
    """
    for item in zip_info:
        if filename == item.filename.split('/')[-1]:
            if item.file_size:
                return item
            else:
                logger.warning('File {} in zip path {} is broken. Expected not empty file. Size = 0'.
                               format(filename, item.filename))
                break
    return None


def extract_packages(logger, archives, destination):
    # type: (Logger, list, str) -> None
    """
    Extract zip packages.
    :param logger: logger instance
    :param archives: list of archives paths
    :param destination: to put files
    """
    for archive in archives:
        try:
            with zipfile.ZipFile(archive) as zipf:
                zipf.extractall(destination)
                logger.debug('Successfully extracted {} to {}'.format(archive, destination))
        except (IOError, OSError) as e:
            logger.debug('Cannot extract archive located in {} to {}. Error: {}'.format(archive, destination, e))
            raise


# Web scraping
def _correct_build_for_trunk(build):
    # type: (str) -> str
    trunk_identifier = '00'
    regex = compile('(^[A-Z]+)(\\d+[^_]+)(_.*_9\\d{3}_)(.*)')

    trunk = regex.match(build)
    if trunk:
        build_in_parts = list(trunk.groups())
        build_in_parts[1] = trunk_identifier
        return ''.join(build_in_parts)
    return build
